begin;
create extension if not exists pgtap with schema extensions;
select plan(15);
insert into auth.users(id,email,role,aud) values ('15600000-0000-4000-8000-000000000001','owner@example.test','authenticated','authenticated'),('15600000-0000-4000-8000-000000000002','forger@example.test','authenticated','authenticated');
insert into public.tavern_saves(id,user_id,current_day,world_phase) values('15600000-0000-4000-8000-000000000010','15600000-0000-4000-8000-000000000001',3,'open');
insert into private.world_settlements(id,save_id,day_number,source_revision,input_fingerprint,status,deadline_at,completed_at) values('15600000-0000-4000-8000-000000000020','15600000-0000-4000-8000-000000000010',3,1,repeat('a',64),'failed',clock_timestamp()+interval '1 hour',clock_timestamp());
insert into private.world_settlement_jobs(id,settlement_id,ordinal,job_kind,status,input_fingerprint,failure_code,completed_at) values('15600000-0000-4000-8000-000000000021','15600000-0000-4000-8000-000000000020',1,'procedural_world','failed',repeat('b',64),'TIMEOUT',clock_timestamp());
insert into private.world_settlement_attempts(job_id,attempt_number,fence,lease_until,status,failure_code,finished_at) values('15600000-0000-4000-8000-000000000021',1,'15600000-0000-4000-8000-000000000022',clock_timestamp(),'failed','TIMEOUT',clock_timestamp());
insert into private.world_canonical_entities(id,save_id,entity_kind,entity_key,origin,source_version,payload,lifecycle,discovered_day) values('15600000-0000-4000-8000-000000000030','15600000-0000-4000-8000-000000000010','npc','inspector-npc','procedural','procedural-world-v1','{"archetypeKey":"supporting-actor"}','active',1);
update private.world_runtime_art_jobs set status='failed_provider',failure_code='failed_provider',completed_at=clock_timestamp() where save_id='15600000-0000-4000-8000-000000000010' and canonical_entity_id='15600000-0000-4000-8000-000000000030';
create temporary table pg_temp.art as select id from private.world_runtime_art_jobs where save_id='15600000-0000-4000-8000-000000000010' and canonical_entity_id='15600000-0000-4000-8000-000000000030';
grant select on pg_temp.art to service_role;
set local role service_role; set local request.jwt.claim.role='service_role';
select throws_ok($$select public.world_developer_requeue_settlement_job('15600000-0000-4000-8000-000000000010','15600000-0000-4000-8000-000000000021','15600000-0000-4000-8000-000000000002','forged actor')$$,'PT403',null,'forged settlement actor is rejected');
select is((public.world_developer_requeue_settlement_job('15600000-0000-4000-8000-000000000010','15600000-0000-4000-8000-000000000021','15600000-0000-4000-8000-000000000001','local retry')->>'status'),'requeued','eligible failed settlement job is requeued');
reset role;
select is((select status from private.world_settlement_jobs where id='15600000-0000-4000-8000-000000000021'),'queued','settlement transition is bounded');
set local role service_role; set local request.jwt.claim.role='service_role';
select throws_ok($$select public.world_developer_requeue_settlement_job('15600000-0000-4000-8000-000000000010','15600000-0000-4000-8000-000000000021','15600000-0000-4000-8000-000000000001','repeat')$$,'PT409',null,'repeated settlement requeue is rejected');
select throws_ok(format($$select public.world_developer_requeue_runtime_art_job('15600000-0000-4000-8000-000000000010',(select id from pg_temp.art),'15600000-0000-4000-8000-000000000002','forged actor')$$),'PT403',null,'forged art actor is rejected');
select is((select public.world_developer_requeue_runtime_art_job('15600000-0000-4000-8000-000000000010',id,'15600000-0000-4000-8000-000000000001','local retry')->>'status' from pg_temp.art),'requeued','eligible failed art job is requeued');
select throws_ok(format($$select public.world_developer_requeue_runtime_art_job('15600000-0000-4000-8000-000000000010',(select id from pg_temp.art),'15600000-0000-4000-8000-000000000001','repeat')$$),'PT409',null,'repeated art requeue is rejected');
select throws_ok($$select public.world_developer_set_runtime_art_appearance('15600000-0000-4000-8000-000000000010','15600000-0000-4000-8000-000000000030','15600000-0000-4000-8000-000000000002','inspector-v2','amber cloak','forged actor')$$,'PT403',null,'forged appearance actor is rejected');
select is((public.world_developer_set_runtime_art_appearance('15600000-0000-4000-8000-000000000010','15600000-0000-4000-8000-000000000030','15600000-0000-4000-8000-000000000001','inspector-v2','amber cloak','local revision')->>'status'),'queued','new art version is queued');
select throws_ok($$select public.world_developer_set_runtime_art_appearance('15600000-0000-4000-8000-000000000010','15600000-0000-4000-8000-000000000030','15600000-0000-4000-8000-000000000001','inspector-v2','other cloak','repeat')$$,'PT409',null,'repeated appearance version is rejected');
select is((public.world_developer_inspector('15600000-0000-4000-8000-000000000010')->>'version'),'world-developer-inspector-v1','service role receives the bounded inspector projection');
reset role;
select is((select count(*) from private.world_developer_overrides),3::bigint,'each successful mutation records exactly one override');
select throws_ok($$update private.world_developer_overrides set summary='rewrite'$$,'55000',null,'override audit is append-only');
select throws_ok($$delete from private.world_developer_overrides$$,'55000',null,'override audit cannot be deleted');
set local role authenticated; set local request.jwt.claim.role='authenticated';
select throws_ok($$select public.world_developer_inspector('15600000-0000-4000-8000-000000000010')$$,'42501',null,'authenticated callers cannot execute inspector projection');
reset role; select * from finish(); rollback;
